def is_balanced(text):
    openers = "([{"
    closers = ")]}"
    stack = []
    for ch in text:
        if ch in openers:
            stack.append(ch)
        elif ch in closers:
            if len(stack) == 0:
                return False
            if openers.index(stack.pop()) != closers.index(ch):
                return False
    return len(stack) == 0
